import type { ImageSourcePropType } from 'react-native';

/** Bundled portraits, generated by scripts/generate_assets.py and shared with the landing page. */
export const portraits = {
  mara: require('../../public/assets/characters/mara.webp'),
  kenji: require('../../public/assets/characters/kenji.webp'),
  keeper: require('../../public/assets/characters/keeper.webp'),
  sorel: require('../../public/assets/characters/sorel.webp'),
  juniper: require('../../public/assets/characters/juniper.webp'),
  rowan: require('../../public/assets/characters/rowan.webp'),
  seraphine: require('../../public/assets/characters/seraphine.webp'),
  arc7: require('../../public/assets/characters/arc7.webp'),
  isla: require('../../public/assets/characters/isla.webp'),
  tallow: require('../../public/assets/characters/tallow.webp'),
  reyes: require('../../public/assets/characters/reyes.webp'),
  odile: require('../../public/assets/characters/odile.webp'),
  gale: require('../../public/assets/characters/gale.webp'),
  lighthouse: require('../../public/assets/characters/lighthouse.webp'),
  masquerade: require('../../public/assets/characters/masquerade.webp'),
  wren: require('../../public/assets/characters/wren.webp'),
  ash: require('../../public/assets/characters/ash.webp'),
} satisfies Record<string, ImageSourcePropType>;

export type PortraitKey = keyof typeof portraits;

/** A stored image reference: a bundled portrait key or a local file uri from the picker. */
export type ImageRef = { kind: 'bundled'; key: PortraitKey } | { kind: 'uri'; uri: string };

export function imageSource(ref?: ImageRef | null): ImageSourcePropType | undefined {
  if (!ref) return undefined;
  if (ref.kind === 'bundled') return portraits[ref.key];
  return { uri: ref.uri };
}
